WITH orders AS (SELECT "wren_src_orders".order_id AS order_id, "wren_src_orders".dept_id AS dept_id, "wren_src_orders".customer_id AS customer_id, "wren_src_orders".industry AS industry, "wren_src_orders".net_amount AS net_amount FROM (SELECT __relation__2.customer_id, __relation__2.dept_id, COALESCE(__relation__2.industry, '未知行业') AS industry, __relation__2.paid_amount - COALESCE(__relation__2.refund_total, CAST(0 AS DECIMAL(38, 10))) AS net_amount, __relation__2.order_id FROM (SELECT customers.customer_id, customers.dept_id, customers.industry, __relation__1.order_id, __relation__1.paid_amount, __relation__1.refund_total FROM (SELECT customers.customer_id, customers.dept_id, customers.industry FROM (SELECT customers.customer_id, customers.dept_id, customers.industry FROM (SELECT __source.customer_id AS customer_id, __source.dept_id AS dept_id, __source.industry AS industry FROM crm."public".customers AS __source) AS customers) AS customers) AS customers RIGHT OUTER JOIN (SELECT orders.customer_id, refund_totals.dept_id, refund_totals.order_id, orders.paid_amount, refund_totals.refund_total FROM (SELECT refund_totals.dept_id, refund_totals.order_id, refund_totals.refund_total FROM (SELECT refund_totals.dept_id, refund_totals.order_id, refund_totals.refund_total FROM (SELECT __source.dept_id AS dept_id, __source.order_id AS order_id, __source.refund_total AS refund_total FROM (SELECT dept_id, order_id, SUM(refund_amount) AS refund_total FROM mysql.sales.refunds GROUP BY dept_id, order_id) AS __source) AS refund_totals) AS refund_totals) AS refund_totals RIGHT OUTER JOIN (SELECT __source.customer_id AS customer_id, __source.dept_id AS dept_id, __source.order_id AS order_id, __source.paid_amount AS paid_amount FROM mysql.sales.orders AS __source) AS orders ON refund_totals.dept_id = orders.dept_id AND refund_totals.order_id = orders.order_id) AS __relation__1 ON customers.dept_id = __relation__1.dept_id AND customers.customer_id = __relation__1.customer_id) AS __relation__2) AS "wren_src_orders") SELECT order_id, dept_id, customer_id, industry, net_amount FROM orders ORDER BY order_id
